import{_ as t,o,c as i,a as n}from"./chunks/plugin-vue_export-helper.F1EaaLXR.js";const g=JSON.parse('{"title":"Лучшие промышленные практики построения AI-агентов, 4 из 10","description":"","frontmatter":{"site":"pro","title":"Лучшие промышленные практики построения AI-агентов, 4 из 10","date":"2026-10-06T00:00:00.000Z","source":"https://t.me/jfyi_ps/96","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-4"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лучшие промышленные практики построения AI-агентов, 4 из 10"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-4"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лучшие промышленные практики построения AI-агентов, 4 из 10"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лучшие промышленные практики построения AI-агентов, 4 из 10\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-4\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-06\\"}"]]},"headers":[],"relativePath":"posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-4.md","filePath":"posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-4.md"}'),r={name:"posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-4.md"};function a(s,e,p,l,c,m){return o(),i("div",null,[...e[0]||(e[0]=[n('<p>Выжимка из книги Ли Боцзе «Глубокое понимание AI Agent: принципы проектирования и инженерная практика» (Pine AI, v2.0, 2026).**</p><ol start="4"><li>Инструменты**</li></ol><p>5 категорий, разные по риску:</p><ul><li>восприятие (read)</li><li>выполнение (exec)</li><li>сотрудничество</li><li>срабатывание события (hook)</li><li>коммуникация с пользователем (question).</li></ul><p>По умолчанию — универсальный инструмент (LLM пишет код/скрипты), специализированный — только при:</p><ul><li>безопасность/права/аудит,</li><li>сложные параметры,</li><li>очень высокая частота,</li><li>различия платформ. Skill vs инструмент — по тем же факторам + частоте изменений + силе модели.</li></ul><p>Объединяй похожие функции параметром. Описание = «когда использовать» + явные границы — большинство ошибок от незнания ограничений, не возможностей. 1-5 примеров вызова поднимают точность сильнее JSON Schema. Чинить описание обычно эффективнее смены модели.</p><p>Никогда не делай тихую нормализацию параметров — создаёт недиагностируемое расхождение модель/реальность. Код как оркестратор нескольких вызовов — экономит на порядки токенов vs прогон через контекст.</p><p>MCP/Skill Hub: description — недоверенный ввод (отравление описания), фикс версий серверов, минимальные credentials, риск tool shadowing.</p><blockquote><p>100 инструментов — иерархия по источнику + семантический предотбор (49%→74%). Агент декларирует потребность на естественном языке, подгрузка динамически; схема дописывается в конец контекста. Skills — самый лёгкий путь к прогрессивному раскрытию.</p></blockquote><p>Восприятие: контекстное сжатие вывода на уровне инструмента; поиск — структурированный список с пагинацией; чтение — offset/limit с явным усечением; read-only — кэшируй и параллель без опаски; мультимодальность — текст (дёшево) vs нативное изображение (важна разметка/пространство).</p><p>Выполнение (высокая цена ошибки): валидация без умной коррекции → контроль доступа с семантическим разбором команд → проверка необратимых (Proposer-Reviewer разных семейств или смена модальности). Sidecar — лёгкая модель видит ТОЛЬКО структурные поля (риск инъекции через текст). Автопроверка сразу (linter после записи). Изоляция: процесс &lt; контейнер &lt; microVM. Идемпотентность для повторяемых операций. Наблюдаемость: логи, аудит, метрики.</p><p>Сотрудничество: маркируй источники в промпте суб-агента ([FROM_MAIN]/[FROM_USER]/[TOOL_RESULT]); стандартизируй формат вывода; примитивы spawn/cancel/send_message/list_agents; HITL — таймаут + консервативный дефолт, решения человека обобщай по случаям, не сразу в правило.</p><p>Продолжение следует...</p>',14)])])}const u=t(r,[["render",a]]);export{g as __pageData,u as default};
